from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
SHARED = ROOT / "tmp/pdfs/next-three/build_next_three_packs.py"
namespace = {}
exec(SHARED.read_text().split("# P1 DAY 4")[0], namespace)
globals().update(namespace)

OUT = ROOT / "output/pdf/next-10-days"


def math_pack(spec):
    story = []
    story += cover(spec["kicker"], spec["title"], spec["subtitle"], spec["aim"],
                   "Read the notes and copy each worked step. Attempt every question before opening page 4. Mark in another colour and repair every error.")
    story += page_title("Learn from zero", "The ideas you need", spec["intro"])
    for note in spec["notes"]:
        story.append(bullet(note))
    story += [Spacer(1, 5), callout("Memory rule", spec["memory"], BLUE_LIGHT, BLUE), Spacer(1, 7)]
    for heading, body in spec["worked"]:
        story += [P(heading, "H2x"), callout("Worked steps", body, TEAL_LIGHT, TEAL), Spacer(1, 5)]
    story += [PageBreak()]
    story += page_title("Your turn", "Independent practice", "Show every step. Include units in Mechanics.")
    rows = [["Question", "Working and final answer"]] + [[q, ""] for q in spec["questions"]]
    story += [table(rows, [84*mm, 90*mm], heights=[9*mm] + [29*mm]*len(spec["questions"])),
              Spacer(1, 7), callout("Stop", "Do not continue until all six questions have an attempt.", ORANGE_LIGHT, ORANGE), PageBreak()]
    story += page_title("Answer section", "Mark, diagnose, correct", "A wrong answer is useful only when you repair the first wrong step.")
    story += [table([["Q", "Answer and essential working"]] + [[str(i+1), a] for i, a in enumerate(spec["answers"])],
                    [16*mm, 158*mm]), Spacer(1, 8),
              table([["Q", "First wrong step", "Correct rule"]] + [["", "", ""] for _ in range(3)],
                    [18*mm, 77*mm, 79*mm], heights=[9*mm]+[20*mm]*3), Spacer(1, 7),
              callout("Send for marking", "Send pages 3 and 4. Ask for a score, the first error in each answer, and one follow-up question per weak skill.", GREEN_LIGHT, TEAL)]
    path = OUT / spec["filename"]
    build(str(path), spec["title"], spec["subtitle"], spec["footer"], story)
    return path


def business_pack(spec):
    story = []
    story += cover(spec["kicker"], spec["title"], spec["subtitle"], spec["aim"],
                   "Read the notes twice. Use exact case facts. Every explanation must contain a because link and a therefore business impact. Keep page 4 closed.")
    story += page_title("Learn from zero", "Knowledge and method", spec["intro"])
    for note in spec["notes"]:
        story.append(bullet(note))
    story += [Spacer(1, 6), callout("Mini case", spec["case"], CREAM, INK), Spacer(1, 6),
              callout("Worked chain", spec["worked"], TEAL_LIGHT, TEAL), PageBreak()]
    story += page_title("Your turn", "Knowledge, application and analysis", "Use the mini case in Questions 3-6.")
    rows = [["Question", "Your answer"]] + [[q, ""] for q in spec["questions"]]
    story += [table(rows, [91*mm, 83*mm], heights=[9*mm]+[29*mm]*len(spec["questions"])), Spacer(1, 7),
              callout("Quality check", "Circle every case fact. Underline every because link. Box every business impact.", ORANGE_LIGHT, ORANGE), PageBreak()]
    story += page_title("Answer section", "Models and correction log", "Wording may differ, but the knowledge and chains must be accurate.")
    story += [table([["Q", "Answer / model points"]] + [[str(i+1), a] for i, a in enumerate(spec["answers"])],
                    [16*mm, 158*mm]), Spacer(1, 7),
              table([["Q", "Missing layer", "My improved sentence"]] + [["", "", ""] for _ in range(3)],
                    [18*mm, 61*mm, 95*mm], heights=[9*mm]+[20*mm]*3), Spacer(1, 7),
              callout("Send for marking", "Send pages 3 and 4. Ask for a level, missing chains, and a rewritten model for the weakest response.", GREEN_LIGHT, TEAL)]
    path = OUT / spec["filename"]
    build(str(path), spec["title"], spec["subtitle"], spec["footer"], story)
    return path


