dict(day=7, filename="p1-day-07-radians.pdf", kicker="AS MATHEMATICS - PURE 1 - DAY 7", title="Radians", subtitle="Angles, arcs, sectors and segments", aim="Use radians confidently in exact geometry problems.", intro="Radians measure an angle using arc length divided by radius.", notes=["pi radians=180 degrees.", "Degrees to radians: multiply by pi/180.", "Arc length s=r theta.", "Sector area=(1/2)r^2 theta.", "Segment area=sector area-triangle area=(1/2)r^2(theta-sin theta)."], memory="The arc and sector formulas require theta in radians.", worked=[("Convert","60 degrees=60(pi/180)=pi/3."),("Sector","r=6, theta=1.2: arc=7.2; area=0.5(36)(1.2)=21.6.")], questions=["1. Convert 135 degrees to radians.","2. Convert 5pi/6 radians to degrees.","3. Find arc length when r=8, theta=0.75.","4. Find sector area when r=5, theta=1.4.","5. Find the perimeter of that sector.","6. Find segment area for r=4, theta=pi/3."], answers=["3pi/4.","150 degrees.","s=8(0.75)=6.","0.5(25)(1.4)=17.5.","2r+s=10+7=17.","0.5(16)(pi/3-sin(pi/3))=8pi/3-4sqrt(3)."], footer="Rohan Study System | P1 Day 7"),
