dict(day=10, filename="p1-day-10-series.pdf", kicker="AS MATHEMATICS - PURE 1 - DAY 10", title="Sequences and series", subtitle="Arithmetic and geometric progressions", aim="Find terms and sums, then decide which model applies.", intro="A progression follows a fixed rule from one term to the next.", notes=["AP: common difference d; nth term a+(n-1)d.", "AP sum: n/2[2a+(n-1)d].", "GP: common ratio r; nth term ar^(n-1).", "GP sum: a(1-r^n)/(1-r).", "Infinite GP sum a/(1-r) only when |r|<1."], memory="Subtract neighbouring terms for an AP; divide them for a GP.", worked=[("AP","3,7,11,... has a=3,d=4. Term 20=3+19(4)=79."),("GP","5,10,20,... has a=5,r=2. Sum first 4=5(1-16)/(1-2)=75.")], questions=["1. Find term 15 of 4,7,10,...","2. Find sum first 20 terms of 2,6,10,...","3. Find term 8 of 3,6,12,...","4. Find sum first 6 terms of 2,6,18,...","5. Find infinite sum 12+6+3+...","6. In an AP, term 3=11 and term 8=31. Find a and d."], answers=["a=4,d=3: 4+14(3)=46.","n/2[2a+(n-1)d]=10[4+76]=800.","3(2^7)=384.","2(1-3^6)/(1-3)=728.","12/(1-1/2)=24.","a+2d=11, a+7d=31, so d=4 and a=3."], footer="Rohan Study System | P1 Day 10"),
